<?php
declare(strict_types=1);
$id='CHAR(36) CHARACTER SET ascii COLLATE ascii_bin';$e=' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci';
$sql=[
"CREATE TABLE support_advanced_confirmations(id $id PRIMARY KEY,actor_id $id NOT NULL,session_id $id NOT NULL,identity_version INT UNSIGNED NOT NULL,action VARCHAR(32) NOT NULL,payload_hmac CHAR(64) NOT NULL,state_hmac CHAR(64) NOT NULL,expires_at DATETIME(6) NOT NULL,used_at DATETIME(6) NULL,FOREIGN KEY(actor_id) REFERENCES identity_users(id),FOREIGN KEY(session_id) REFERENCES identity_sessions(id))$e",
"CREATE TABLE support_rule_heads(id $id PRIMARY KEY,department_id $id NOT NULL,customer_id $id NOT NULL,revision_id $id NULL,version INT UNSIGNED NOT NULL DEFAULT 0,FOREIGN KEY(department_id) REFERENCES support_departments(id),FOREIGN KEY(customer_id) REFERENCES identity_customers(id),KEY ix_rule_scope(department_id,customer_id))$e",
"CREATE TABLE support_rule_revisions(id $id PRIMARY KEY,rule_id $id NOT NULL,revision INT UNSIGNED NOT NULL,spec LONGTEXT NOT NULL CHECK(JSON_VALID(spec)),enabled BOOLEAN NOT NULL,ordering INT NOT NULL,sponsor_id $id NOT NULL,session_id $id NOT NULL,identity_version INT UNSIGNED NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE(rule_id,revision),UNIQUE(rule_id,id),FOREIGN KEY(rule_id) REFERENCES support_rule_heads(id),FOREIGN KEY(sponsor_id) REFERENCES identity_users(id),FOREIGN KEY(session_id) REFERENCES identity_sessions(id))$e",
"ALTER TABLE support_rule_heads ADD FOREIGN KEY(id,revision_id) REFERENCES support_rule_revisions(rule_id,id)",
"CREATE TABLE support_incidents(id $id PRIMARY KEY,department_id $id NOT NULL,title_encrypted TEXT NOT NULL,description_encrypted TEXT NOT NULL,root_encrypted TEXT NOT NULL,affected_encrypted TEXT NOT NULL,status VARCHAR(24) NOT NULL CHECK(status IN ('INVESTIGATING','IDENTIFIED','MONITORING','RESOLVED')),started_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),resolved_at DATETIME(6) NULL,version INT UNSIGNED NOT NULL DEFAULT 1,created_by $id NOT NULL,FOREIGN KEY(department_id) REFERENCES support_departments(id),FOREIGN KEY(created_by) REFERENCES identity_users(id),KEY ix_incident_department(department_id,started_at,id))$e",
"CREATE TABLE support_incident_updates(id $id PRIMARY KEY,incident_id $id NOT NULL,version INT UNSIGNED NOT NULL,status VARCHAR(24) NOT NULL CHECK(status IN ('INVESTIGATING','IDENTIFIED','MONITORING','RESOLVED')),public_encrypted TEXT NOT NULL,private_encrypted TEXT NOT NULL,actor_id $id NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE(incident_id,version),FOREIGN KEY(incident_id) REFERENCES support_incidents(id),FOREIGN KEY(actor_id) REFERENCES identity_users(id))$e",
"CREATE TABLE support_incident_tickets(incident_id $id NOT NULL,ticket_id $id NOT NULL,customer_id $id NOT NULL,actor_id $id NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),PRIMARY KEY(incident_id,ticket_id),FOREIGN KEY(incident_id) REFERENCES support_incidents(id),FOREIGN KEY(ticket_id,customer_id) REFERENCES support_tickets(id,customer_id),FOREIGN KEY(actor_id) REFERENCES identity_users(id))$e",
"CREATE TABLE support_automation_events(id $id PRIMARY KEY,source_kind VARCHAR(16) NOT NULL CHECK(source_kind IN ('SUPPORT','WORK','INCIDENT','OPERATION')),source_id $id NOT NULL,ticket_id $id NOT NULL,customer_id $id NOT NULL,department_id $id NOT NULL,trigger_name VARCHAR(32) NOT NULL,source_ticket_version INT UNSIGNED NOT NULL,causation_id $id NOT NULL,correlation_id $id NOT NULL,parent_id $id NULL,depth TINYINT UNSIGNED NOT NULL CHECK(depth<=4),chain_json TEXT NOT NULL CHECK(JSON_VALID(chain_json)),rule_snapshot LONGTEXT NOT NULL CHECK(JSON_VALID(rule_snapshot)),created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE(source_kind,source_id,ticket_id),FOREIGN KEY(ticket_id,customer_id) REFERENCES support_tickets(id,customer_id),FOREIGN KEY(department_id) REFERENCES support_departments(id),FOREIGN KEY(parent_id) REFERENCES support_automation_events(id))$e",
"CREATE TABLE support_rule_executions(id $id PRIMARY KEY,event_uuid $id NOT NULL,rule_revision $id NOT NULL,rule_id $id NOT NULL,source_ticket_version INT UNSIGNED NOT NULL,causation_id $id NOT NULL,correlation_id $id NOT NULL,sponsor_id $id NOT NULL,actor_kind VARCHAR(16) NOT NULL CHECK(actor_kind='SYSTEM_RULE'),result VARCHAR(24) NOT NULL CHECK(result IN ('MATCH','NO_MATCH','UNAVAILABLE','APPLIED','SKIPPED','FAILED','LOOP_BLOCKED')),reason VARCHAR(48) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE(event_uuid,rule_revision),FOREIGN KEY(event_uuid) REFERENCES support_automation_events(id),FOREIGN KEY(rule_revision) REFERENCES support_rule_revisions(id),FOREIGN KEY(rule_id) REFERENCES support_rule_heads(id),FOREIGN KEY(sponsor_id) REFERENCES identity_users(id))$e",
"CREATE TABLE support_rule_action_results(id $id PRIMARY KEY,execution_id $id NOT NULL,event_uuid $id NOT NULL,rule_revision $id NOT NULL,action_no TINYINT UNSIGNED NOT NULL,kind VARCHAR(24) NOT NULL,result VARCHAR(24) NOT NULL CHECK(result IN ('APPLIED','SKIPPED')),effect_id $id NULL,UNIQUE(event_uuid,rule_revision,action_no),FOREIGN KEY(execution_id) REFERENCES support_rule_executions(id),FOREIGN KEY(event_uuid) REFERENCES support_automation_events(id),FOREIGN KEY(rule_revision) REFERENCES support_rule_revisions(id))$e",
"CREATE TABLE support_advanced_events(id $id PRIMARY KEY,ticket_id $id NULL,customer_id $id NULL,department_id $id NOT NULL,subject_id $id NOT NULL,kind VARCHAR(32) NOT NULL,actor_id VARCHAR(64) NOT NULL,sponsor_id $id NULL,execution_id $id NULL,details LONGTEXT NOT NULL CHECK(JSON_VALID(details)),trace_id $id NOT NULL,causation_id $id NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(ticket_id,customer_id) REFERENCES support_tickets(id,customer_id),FOREIGN KEY(department_id) REFERENCES support_departments(id),FOREIGN KEY(sponsor_id) REFERENCES identity_users(id),KEY ix_advanced_ticket(ticket_id,created_at,id))$e",
"CREATE TABLE support_ticket_tags(ticket_id $id NOT NULL,customer_id $id NOT NULL,tag VARCHAR(48) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,source_id $id NOT NULL,PRIMARY KEY(ticket_id,tag),FOREIGN KEY(ticket_id,customer_id) REFERENCES support_tickets(id,customer_id),FOREIGN KEY(source_id) REFERENCES support_advanced_events(id))$e",
"CREATE TABLE support_staff_held(id $id PRIMARY KEY,ticket_id $id NOT NULL,customer_id $id NOT NULL,department_id $id NOT NULL,execution_id $id NOT NULL,status VARCHAR(8) NOT NULL CHECK(status='HELD'),FOREIGN KEY(ticket_id,customer_id) REFERENCES support_tickets(id,customer_id),FOREIGN KEY(execution_id) REFERENCES support_rule_executions(id))$e",
"CREATE TABLE support_csat_policies(department_id $id PRIMARY KEY,window_seconds INT UNSIGNED NOT NULL CHECK(window_seconds BETWEEN 1 AND 31536000),version INT UNSIGNED NOT NULL,FOREIGN KEY(department_id) REFERENCES support_departments(id))$e",
"CREATE TABLE support_ratings(ticket_id $id PRIMARY KEY,customer_id $id NOT NULL,resolution_event $id NOT NULL,revision_id $id NULL,version INT UNSIGNED NOT NULL DEFAULT 0,FOREIGN KEY(ticket_id,customer_id) REFERENCES support_tickets(id,customer_id),FOREIGN KEY(resolution_event) REFERENCES support_events(id))$e",
"CREATE TABLE support_rating_revisions(id $id PRIMARY KEY,ticket_id $id NOT NULL,customer_id $id NOT NULL,revision INT UNSIGNED NOT NULL,score TINYINT UNSIGNED NOT NULL CHECK(score BETWEEN 1 AND 5),comment_encrypted TEXT NOT NULL,policy_version INT UNSIGNED NOT NULL,window_seconds INT UNSIGNED NOT NULL,actor_id $id NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE(ticket_id,revision),UNIQUE(ticket_id,id),FOREIGN KEY(ticket_id,customer_id) REFERENCES support_tickets(id,customer_id),FOREIGN KEY(actor_id) REFERENCES identity_users(id))$e",
"ALTER TABLE support_ratings ADD FOREIGN KEY(ticket_id,revision_id) REFERENCES support_rating_revisions(ticket_id,id)",
];
foreach(['support.automation.manage','support.incident.manage','support.report.view'] as $p){$sql[]="INSERT INTO identity_permissions(code) VALUES ('$p')";$sql[]="INSERT INTO identity_role_permissions(role_id,permission) SELECT id,'$p' FROM identity_roles WHERE name IN ('Super Admin','Destek')";}
foreach(['support_rule_revisions','support_incident_updates','support_incident_tickets','support_automation_events','support_rule_executions','support_rule_action_results','support_advanced_events','support_ticket_tags','support_staff_held','support_rating_revisions'] as $t){foreach(['UPDATE','DELETE'] as $verb){$sql[]="CREATE TRIGGER {$t}_no_".strtolower($verb)." BEFORE $verb ON $t FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable support advanced record'";}}
foreach(['support_rule_heads','support_incidents','support_csat_policies','support_ratings'] as $t){$sql[]="CREATE TRIGGER {$t}_no_delete BEFORE DELETE ON $t FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Preserve support advanced history'";}
$sql[]="CREATE TRIGGER support_rule_heads_identity BEFORE UPDATE ON support_rule_heads FOR EACH ROW BEGIN IF NOT(OLD.id<=>NEW.id) OR NOT(OLD.department_id<=>NEW.department_id) OR NOT(OLD.customer_id<=>NEW.customer_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable rule scope'; END IF; END";
$sql[]="CREATE TRIGGER support_incidents_identity BEFORE UPDATE ON support_incidents FOR EACH ROW BEGIN IF NOT(OLD.id<=>NEW.id) OR NOT(OLD.department_id<=>NEW.department_id) OR NOT(OLD.started_at<=>NEW.started_at) OR NOT(OLD.created_by<=>NEW.created_by) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable incident identity'; END IF; END";
$sql[]="CREATE TRIGGER support_ratings_identity BEFORE UPDATE ON support_ratings FOR EACH ROW BEGIN IF NOT(OLD.ticket_id<=>NEW.ticket_id) OR NOT(OLD.customer_id<=>NEW.customer_id) OR NOT(OLD.resolution_event<=>NEW.resolution_event) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable rating ownership'; END IF; END";
return $sql;
